import React, {useEffect, useRef, useState} from 'react';
import {
  CARD_TOP_INSET,
  clampCardLayout,
  parseCardLayout,
  snapCardRect,
  type CardLayout,
  type CardRect,
  type ViewportSize
} from '../featureCard/cardLayout';
import {CardSettingsProvider} from '../featureCard/cardSettingsContext';
import {featureCardKey, PIN_CARDS_EVENT} from '../featureCard/pinCards';
import {useT} from '../i18n/i18n';
import {CloseIcon, GearIcon, PinIcon} from './icons';
import styles from './FeatureCard.module.css';

type FeatureCardProps = {
  id: string;
  title: string;
  defaultLayout: CardLayout;
  frontNonce?: number;
  onClose: () => void;
  children: React.ReactNode;
};

type DragState = {
  pointerId: number;
  originX: number;
  originY: number;
  startX: number;
  startY: number;
  startWidth: number;
  startHeight: number;
  mode: 'move' | 'resize';
  others: CardRect[];
  gap: number;
};

function viewportSize(): ViewportSize {
  return {width: window.innerWidth, height: window.innerHeight};
}

function cardTopInset(): number {
  const mast = document.querySelector('.mast');
  if (!(mast instanceof HTMLElement)) {
    return CARD_TOP_INSET;
  }
  return Math.ceil(mast.getBoundingClientRect().bottom);
}

const DEFAULT_CARD_GAP = 16;

function cardGap(): number {
  const value = parseFloat(
    getComputedStyle(document.documentElement).getPropertyValue('--gap')
  );
  return Number.isFinite(value) ? value : DEFAULT_CARD_GAP;
}

function otherCardRects(self: HTMLElement): CardRect[] {
  return Array.from(document.querySelectorAll(`.${styles.card}`))
    .filter(element => element !== self)
    .map(element => {
      const rect = element.getBoundingClientRect();
      return {x: rect.left, y: rect.top, width: rect.width, height: rect.height};
    });
}

function boundCardLayout(layout: CardLayout): CardLayout {
  return clampCardLayout(layout, viewportSize(), cardTopInset());
}

type StoredCard = CardLayout & {placed?: boolean};

function readStoredCard(
  id: string,
  fallback: CardLayout
): {layout: CardLayout; placed: boolean} {
  const raw = localStorage.getItem(featureCardKey(id));
  if (!raw) {
    return {layout: fallback, placed: false};
  }
  try {
    const parsed: unknown = JSON.parse(raw);
    const layout = boundCardLayout(parseCardLayout(parsed, fallback));
    const placed =
      !!parsed &&
      typeof parsed === 'object' &&
      ('placed' in parsed ? Boolean((parsed as StoredCard).placed) : true);
    return {layout, placed};
  } catch {
    return {layout: boundCardLayout(fallback), placed: false};
  }
}

let zSeed = 2;

export default function FeatureCard({
  id,
  title,
  defaultLayout,
  frontNonce = 0,
  onClose,
  children
}: FeatureCardProps) {
  const stored = useRef(readStoredCard(id, defaultLayout));
  const [layout, setLayout] = useState<CardLayout>(stored.current.layout);
  const [placed, setPlaced] = useState(stored.current.placed);
  const [zIndex, setZIndex] = useState(1);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const dragRef = useRef<DragState | null>(null);
  const sectionRef = useRef<HTMLElement>(null);
  const t = useT();

  const bringToFront = () => {
    const rect = sectionRef.current?.getBoundingClientRect();
    zSeed += 1;
    setZIndex(zSeed);
    if (!rect) {
      return;
    }
    setPlaced(true);
    setLayout(current =>
      boundCardLayout({
        ...current,
        x: rect.left,
        y: rect.top,
        width: rect.width,
        height: rect.height
      })
    );
  };

  useEffect(() => {
    if (!placed && !layout.pinned && !localStorage.getItem(featureCardKey(id))) {
      return;
    }
    const record: StoredCard = {...layout, placed};
    localStorage.setItem(featureCardKey(id), JSON.stringify(record));
  }, [id, layout, placed]);

  useEffect(() => {
    const onPinCards = (event: Event) => {
      const pinned = Boolean((event as CustomEvent<boolean>).detail);
      setLayout(current => (current.pinned === pinned ? current : {...current, pinned}));
    };
    window.addEventListener(PIN_CARDS_EVENT, onPinCards);
    return () => window.removeEventListener(PIN_CARDS_EVENT, onPinCards);
  }, []);

  useEffect(() => {
    setLayout(current => boundCardLayout(current));
  }, []);

  useEffect(() => {
    if (!frontNonce) {
      return;
    }
    bringToFront();
  }, [frontNonce]);

  useEffect(() => {
    if (!placed) {
      return;
    }
    const onResize = () => setLayout(current => boundCardLayout(current));
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, [placed]);

  const beginPointer =
    (mode: DragState['mode']) => (event: React.PointerEvent<HTMLElement>) => {
      if (layout.pinned || event.button !== 0) {
        return;
      }
      const target = event.target;
      if (mode === 'move' && target instanceof Element && target.closest('button')) {
        return;
      }
      const section = sectionRef.current;
      if (!section) {
        return;
      }
      const rect = section.getBoundingClientRect();
      event.currentTarget.setPointerCapture(event.pointerId);
      dragRef.current = {
        pointerId: event.pointerId,
        originX: event.clientX,
        originY: event.clientY,
        startX: rect.left,
        startY: rect.top,
        startWidth: rect.width,
        startHeight: rect.height,
        mode,
        others: otherCardRects(section),
        gap: cardGap()
      };
      if (!placed) {
        setLayout(current => ({
          ...current,
          x: rect.left,
          y: rect.top,
          width: rect.width,
          height: rect.height
        }));
        setPlaced(true);
      }
      zSeed += 1;
      setZIndex(zSeed);
    };

  const movePointer = (event: React.PointerEvent<HTMLElement>) => {
    const drag = dragRef.current;
    if (!drag || drag.pointerId !== event.pointerId || layout.pinned) {
      return;
    }
    const dx = event.clientX - drag.originX;
    const dy = event.clientY - drag.originY;
    const next =
      drag.mode === 'move'
        ? {
            x: drag.startX + dx,
            y: drag.startY + dy,
            width: drag.startWidth,
            height: drag.startHeight
          }
        : {
            x: drag.startX,
            y: drag.startY,
            width: drag.startWidth + dx,
            height: drag.startHeight + dy
          };
    const snapped = snapCardRect(next, drag.others, drag.mode, drag.gap);
    setLayout(current => boundCardLayout({...current, ...snapped}));
  };

  const endPointer = (event: React.PointerEvent<HTMLElement>) => {
    if (dragRef.current?.pointerId === event.pointerId) {
      dragRef.current = null;
    }
  };

  return (
    <CardSettingsProvider
      value={{isOpen: settingsOpen, close: () => setSettingsOpen(false)}}
    >
      <section
        ref={sectionRef}
        className={styles.card}
        style={
          placed
            ? {
                left: layout.x,
                top: layout.y,
                width: layout.width,
                height: layout.height,
                zIndex
              }
            : undefined
        }
        data-placed={placed}
        data-pinned={layout.pinned}
        aria-label={title}
      >
        <header
          className={styles.header}
          onPointerDown={beginPointer('move')}
          onPointerMove={movePointer}
          onPointerUp={endPointer}
        >
          <h2 className={styles.title}>{title}</h2>
          <span className={styles.actions}>
            <button
              type="button"
              className="icon-button"
              aria-label={t('card.settings', {title})}
              onClick={() => setSettingsOpen(true)}
            >
              <GearIcon />
            </button>
            <button
              type="button"
              className="icon-button"
              aria-pressed={layout.pinned}
              aria-label={t('card.pin', {title})}
              onClick={() =>
                setLayout(current => ({...current, pinned: !current.pinned}))
              }
            >
              <PinIcon filled={layout.pinned} />
            </button>
            <button
              type="button"
              className="icon-button"
              aria-label={t('card.close', {title})}
              onClick={onClose}
            >
              <CloseIcon />
            </button>
          </span>
        </header>
        <div className={styles.body}>{children}</div>
        {layout.pinned ? null : (
          <div
            className={styles.resize}
            aria-hidden="true"
            onPointerDown={beginPointer('resize')}
            onPointerMove={movePointer}
            onPointerUp={endPointer}
          />
        )}
      </section>
    </CardSettingsProvider>
  );
}
